def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for m in opp if m == 'C')
    opp_c_rate = opp_c / n

    if n >= 3 and opp_c_rate <= 0.2:
        return 'D'

    my_d = sum(1 for m in my if m == 'D')

    if my_d == 0 and n >= 5:
        return 'D'

    if my_d == 1 and my[-1] == 'D' and n >= 6:
        return 'C'

    total_after_my_d = 0
    opp_d_after_my_d = 0
    total_after_my_c = 0
    opp_d_after_my_c = 0

    for i in range(n - 1):
        if my[i] == 'D':
            total_after_my_d += 1
            if opp[i+1] == 'D':
                opp_d_after_my_d += 1
        else:
            total_after_my_c += 1
            if opp[i+1] == 'D':
                opp_d_after_my_c += 1

    punish_rate = opp_d_after_my_d / total_after_my_d if total_after_my_d > 0 else 0.0
    aggression_rate = opp_d_after_my_c / total_after_my_c if total_after_my_c > 0 else 0.0

    if n == 100:
        return 'D'

    if aggression_rate > 0.2:
        return 'D'
    if punish_rate > 0.5:
        return 'C'
    if punish_rate < 0.15 and aggression_rate < 0.15:
        return 'D'

    if opp[-1] == 'C':
        return 'C'
    else:
        return 'D'
